def definitions(schema, string):
    identity = {'id': string(100)}
    source = {'repository': string(2000), 'ref': string(500), 'path': string(1000)}
    return {
        'smartTools.catalog': ('Refresh the public Smart Tools catalog; listing does not install or run code.', schema()),
        'smartTools.inspect': ('Read a Git Smart Tool descriptor and manifest without running its code.', schema(source, ['repository'])),
        'smartTools.setup': ('Read one installed tool’s exact source documentation and declared CLI guidance. Does not run checks, connect, configure credentials or imply readiness. Follow nextOffset for the complete manifest.', schema({**identity,'offset':{'type':'integer','minimum':0},'limit':{'type':'integer','minimum':1,'maximum':16000}}, ['id'])),
        'smartTools.install': ('Install a Python Git Smart Tool in an isolated environment. Does not start it or configure models.', schema({**source, 'extras': {'type':'array','maxItems':20,'items':string(100)}}, ['repository'])),
        'smartTools.installBatch': ('Install selected catalog items with individual progress; retryOperationId retries only failed or interrupted items from that batch.', schema({'ids':{'type':'array','minItems':1,'maxItems':200,'uniqueItems':True,'items':string(200)},'retryOperationId':string(100),'extrasById':{'type':'object','maxProperties':200,'additionalProperties':{'type':'array','maxItems':20,'items':string(100)}}}, [])),
        'smartTools.configure': ('Register an MCP stdio or Streamable HTTP server. env/headers map names to host environment variable names, never secret values. OAuth requires explicit authStart; configuration does not connect.', schema({**identity, 'name':string(200), 'transport':{'enum':['stdio','streamable-http']}, 'command':string(4000), 'args':{'type':'array','maxItems':100,'items':string(4000)}, 'env':{'type':'object','maxProperties':50,'additionalProperties':string(200)}, 'headers':{'type':'object','maxProperties':50,'additionalProperties':string(200)}, 'url':string(2000), 'auth':{'enum':['environment','oauth']}, 'installationId':string(100), 'cwd':string(4000)}, ['name'])),
        'smartTools.reconnect': ('Close and explicitly reconnect with current credentials. Does not replay prior calls.', schema(identity, ['id'])),
        'smartTools.authStart': ('Start SDK OAuth sign-in. The user must open the returned authorization URL and complete consent. redirectOrigin must be a configured app origin. Never complete provider consent autonomously.', schema({**identity,'redirectOrigin':string(2000)}, ['id'])),
        'smartTools.authStatus': ('Read sign-in progress, requested/granted scopes and attributable account identity when supported. Does not connect.', schema(identity, ['id'])),
        'smartTools.accountAccept': ('Accept the exact changed connector-attested issuer and subject after reviewing the current account. Records a decision; never connects or calls tools. Reconnect explicitly afterward.', schema({**identity, 'expectedRevision':{'type':'integer','minimum':0}, 'issuer':string(2000), 'subject':string(500)}, ['id','expectedRevision','issuer','subject'])),
        'smartTools.authCancel': ('Cancel pending sign-in; does not revoke an existing provider grant.', schema(identity, ['id'])),
        'smartTools.authForget': ('Disconnect and remove locally stored OAuth credentials. Remote authorization is not revoked; use the provider account controls for revocation.', schema(identity, ['id'])),
        'smartTools.uninstall': ('Remove one app-managed package only after all dependent connection registrations have been removed. Only the app-managed installation folder is removed; work stored elsewhere is kept.', schema(identity, ['id'])),
        'smartTools.discover': ('Search model-visible tool summaries on an explicitly connected server. refresh re-lists a stale catalog without invoking tools. No schemas are loaded.', schema({**identity,'query':string(500),'refresh':{'type':'boolean'},'offset':{'type':'integer','minimum':0},'limit':{'type':'integer','minimum':1,'maximum':25},'catalogRevision':string(100)}, ['id'])),
        'smartTools.schemas': ('Load one to five exact callable schemas (64 KB maximum) from a current catalog. Include catalogRevision in the subsequent call. UI-only tools are excluded.', schema({**identity,'names':{'type':'array','minItems':1,'maxItems':5,'items':string(200)},'catalogRevision':string(100)}, ['id','names','catalogRevision'])),
        'smartTools.connect': ('Connect this configured MCP server and discover compact tool summaries. Never starts interactive sign-in.', schema(identity)),
        'smartTools.disconnect': ('Disconnect this MCP server. Tool-owned durable work may continue independently.', schema(identity)),
        'smartTools.remove': ('Remove this server registration, keeping installed files and tool-owned work.', schema(identity)),
        'smartTools.call': ('Call a discovered model-visible tool. Read the returned operationId with smartTools.readResult. A timeout is not proof that tool-owned work stopped; inspect its status before retrying.', schema({**identity,'name':string(200),'arguments':{'type':'object'},'catalogRevision':string(100),'sessionId':string(200),'timeoutSeconds':{'type':'number','minimum':1,'maximum':300}}, ['id','name'])),
        'smartTools.readResult': ('Read a retained operation by ID synchronously without creating work. Follow $operationPath using path, offset, limit and operationRevision. format=json pages the whole operation without path, also used automatically for oversized keys. Never use rolling list indices as identities.', schema({'operationId':string(100),'path':string(4000),'format':{'enum':['structured','json']},'offset':{'type':'integer','minimum':0},'limit':{'type':'integer','minimum':1,'maximum':16000},'operationRevision':string(64)}, ['operationId'])),
        'smartTools.result': ('Inspect an older or large operation result in /smartTools/inspectedOperation. Follow $resource state paths for paged content.', schema({'operationId':string(100)})),
        'smartTools.resources': ('List a connected MCP server’s resources or resource templates, one page at a time. Resource reads are bounded to 2 MB; use the tool’s chunk resources for media.', schema({**identity,'kind':{'enum':['list','templates']},'cursor':string(4000)}, ['id'])),
        'smartTools.readResource': ('Read a resource URI through this connected MCP server. The host never fetches the URI directly. Use tool-provided bounded chunks for large media.', schema({**identity,'uri':string(4000)}, ['id','uri'])),
        'smartTools.open': ('Open a discovered MCP App in a durable canvas tab. Supply operationId to send that call’s arguments and result to the view. Closing a tab does not cancel tool work.', schema({**identity,'tool':string(200),'operationId':string(100),'sessionId':string(200)}, ['id','tool'])),
        'smartTools.viewStatus': ('Inspect saved source and live connection availability for the active tool view in the calling chat. Does not connect or replay calls.', schema({'canvasId':string(100),'clientId':string(100)}, ['canvasId'])),
        'smartTools.reconnectView': ('Reconnect the same saved tool view without replacing its document or replaying calls. Inspect first; older views return a contract review. Supply that exact reviewedContract fingerprint only after reviewing the existing grants.', schema({'canvasId':string(100),'clientId':string(100),'expectedBindingRevision':string(64),'reviewedContract':string(64)}, ['canvasId','expectedBindingRevision'])),
        'smartTools.appCall': ('Call an app-visible tool through the current canvas binding. Cannot select a different server. Results also appear in shared smartTools.operations.', schema({'canvasId':string(100),'expectedRevision':{'type':'integer','minimum':1},'name':string(200),'arguments':{'type':'object'}}, ['canvasId','name'])),
        'smartTools.context': ('Record the current MCP App view context as untrusted display data, visible to the agent on its next state read. Does not start a model turn.', schema({'canvasId':string(100),'expectedRevision':{'type':'integer','minimum':1},'context':{'type':'object'}}, ['canvasId','context'])),
    }
